/**
 * This methods accepts an array of points, a global radius, and some options.
 * It will return an array of points corresponding to the curve approximation (since
 * lines and curves cannot be mixed in a shape in p5), so each line is rounded by
 * the given radius.
 * The points (in [x, y] format) can optionally have a third element, which is the
 * radius for the particular point used as angle pivot
 * @param {*} points Array of points in [x, y] format, optionally with a third element radius
 * @param {*} radius Global radius for all points
 * @param {*} options Options object
 * @param {*} options.stepSize Step size (angle in degrees) for the curve approximation
 * @param {*} options.includeEnds Whether to include the end points as part of the result
 * @param {*} options.closed Whether the shape is closed or not
 * @returns
 */
 function smoothLine(points, radius, { stepSize = 10, includeEnds = true, closed = false } = {}) {
  angleMode(DEGREES)

  if (closed) {
    points = [...points, points[0], points[1]]
  }
  let p1, p2, p3

  let result = []
  if (includeEnds && !closed) {
    result.push(points[0])
  }
  for (let i = 0; i < points.length - 2; i++) {
    p1 = points[i]
    p2 = points[i + 1]
    p3 = points[i + 2]

    let A = createVector(p1[0], p1[1])
    let B = createVector(p2[0], p2[1])
    let C = createVector(p3[0], p3[1])

    let BA = A.sub(B)
    let BC = C.sub(B)

    let BAnorm = BA.copy().normalize()
    let BCnorm = BC.copy().normalize()

    let sinA = -BAnorm.dot(BCnorm.copy().rotate(90))
    let sinA90 = BAnorm.dot(BCnorm)
    let angle = asin(sinA)

    let radDirection = 1
    let drawDirection = false
    let localRadius = radius
    if (p2[2] !== undefined) {
      localRadius = p2[2]
    }

    if (sinA90 < 0) {
      if (angle >= 0) {
        radDirection = -1
        drawDirection = true
      }
      angle += 180
    } else {
      if (angle > 0) {
        radDirection = -1
        drawDirection = true
      }
    }

    let halfAngle = angle / 2
    let lenOut = abs((cos(halfAngle) * localRadius) / sin(halfAngle))

    let cRadius

    if (lenOut > min(BA.mag() / 2, BC.mag() / 2)) {
      lenOut = min(BA.mag() / 2, BC.mag() / 2)
      cRadius = abs((lenOut * sin(halfAngle)) / cos(halfAngle))
    } else {
      cRadius = localRadius
    }

    let cx = B.x + BC.normalize().x * lenOut - BC.normalize().y * cRadius * radDirection
    let cy = B.y + BC.normalize().y * lenOut + BC.normalize().x * cRadius * radDirection


    let startAngle = BA.heading() + (90) * radDirection
    let endAngle = BC.heading() - (90) * radDirection

    if (drawDirection) {
      [startAngle, endAngle] = [endAngle, startAngle]
    }
    if (startAngle > endAngle) {
      endAngle += 360
    }

    let step = stepSize || 10
    if (!drawDirection) {
      for (let a = startAngle; a < endAngle; a += (Math.max(0.001, Math.abs(step)) || 1)) {
        let arcX = cx + cRadius * cos(a)
        let arcY = cy + cRadius * sin(a)
        result.push([arcX, arcY])
      }
    } else {
      for (let a = endAngle; a > startAngle; a -= step) {
        let arcX = cx + cRadius * cos(a)
        let arcY = cy + cRadius * sin(a)
        result.push([arcX, arcY])
      }
    }
  }
  if (includeEnds && !closed) {
    result.push(points[points.length - 1])
  }
  if (closed) {
    result.push(result[0])
  }
  return result
}

