  //   x * NOISE_FACTOR + frameCount / CHANGE_SPEED,
  //   y * NOISE_FACTOR + frameCount / CHANGE_SPEED
  // ) // Add frameCount to change over time, but need to regenerate the diagram
  return noise(x * NOISE_FACTOR, y * NOISE_FACTOR)
}

function getBiomeIndex(x, y) {
  let heightValue = getHeightValue(x, y)
  // Normal-ish distributed among normal distribution...
  if (heightValue < 0.388) {
    return 0
  } else if (heightValue < 0.5) {
    return 1
  } else if (heightValue < 0.611) {
    return 2
  } else {
    return 3
  }
}

function getNeighbors(cell) {
  let neighbors = []
  cell.halfedges.forEach((halfedge) => {
    if (
      halfedge.edge.lSite &&
      halfedge.edge.lSite.voronoiId !== cell.site.voronoiId
    ) {
      if (
        !neighbors.some(
          (c) => c.site.voronoiId === halfedge.edge.lSite.voronoiId
        )
      ) {
        neighbors.push(DIAGRAM.cells[halfedge.edge.lSite.voronoiId])
      }
    }
    if (
      halfedge.edge.rSite &&
      halfedge.edge.rSite.voronoiId !== cell.site.voronoiId
    ) {
      if (
        !neighbors.some(
          (c) => c.site.voronoiId === halfedge.edge.rSite.voronoiId
        )
      ) {
        neighbors.push(DIAGRAM.cells[halfedge.edge.rSite.voronoiId])
      }
    }
  })
  return neighbors
}

const areEqualPoints = (p1, p2) => {
  // Bullshit js float precision, Number.EPSILON is not enough
  return (
    Math.abs(p1.x - p2.x) < 0.0001 &&
    Math.abs(p1.y - p2.y) < 0.0001
  )
}

let BIOMES = null
function updateShapes(diagram) {
  let clusters = getBiomes(diagram)
  BIOMES = clusters.map((cluster) => ({
    cluster,
    perimeter: getClusterPerimeter(cluster)
  }))
  for (let cell of diagram.cells) {
    // TODO: Can invalidate only the cells that changed
    delete cell.smoothedCell
  }
}

function getBiomes(diagram) {
  let clusters = []
  for (let cell of diagram.cells) {
    let cluster
    let biomeIndex = getBiomeIndex(cell.site.x, cell.site.y)
    let biomeNeighbors = getNeighbors(cell).filter(
      (c) => getBiomeIndex(c.site.x, c.site.y) === biomeIndex
    )
    let biomeNeighborClusters = biomeNeighbors
      .map((c) => {
        return clusters.find((cluster) => {
          return cluster.cells.some((c2) => {
            return c.site.voronoiId === c2.site.voronoiId
          })
        })
      })
      .filter(Boolean)
    biomeNeighborClusters = biomeNeighborClusters.filter(
      (c, i) => biomeNeighborClusters.indexOf(c) === i
    )

    if (biomeNeighborClusters.length === 0) {
      cluster = { cells: [cell], type: biomeIndex }
      clusters.push(cluster)
      cluster.cells.push(...biomeNeighbors)
      // for (let neighbor of biomeNeighbors) {
      //   cluster.cells.push(neighbor)
      // }
    } else if (biomeNeighborClusters.length === 1) {
      cluster = biomeNeighborClusters[0]
      if (!cluster.cells.some((c) => c.site.voronoiId === cell.site.voronoiId)) {
        cluster.cells.push(cell)
      }
    } else {
      // Merge all clusters into the first one
      cluster = { cells: [], type: biomeIndex }
      cluster.cells.push(cell)
      biomeNeighborClusters.forEach((c) => {
        c.cells.forEach((cell) => {
          if (!cluster.cells.some((c2) => c2.site.voronoiId === cell.site.voronoiId)) {
            cluster.cells.push(cell)
          }
        })
        clusters.splice(clusters.indexOf(c), 1)
      })
      clusters.push(cluster)
    }
  }
  return clusters
}

function getClusterPerimeter(cluster) {
  let edges = new Set()
  for (let cell of cluster.cells) {
    for (let halfedge of cell.halfedges) {
      edges.add(halfedge)
    }
  }

  let W = (angle) => {
    return F(degrees(angle))
  }
  let F = (a) => {
    if (a < 0) { return a + 360 }
    if (a > 360) { return a % 360 }
    return a
  }
  let topEdge = [...edges].reduce((a, b) => {
    if (a.getStartpoint().y < b.getStartpoint().y) {
      return a
    } else if (a.getStartpoint().y > b.getStartpoint().y) {
      return b
    } else {
      return W(a.angle) > W(b.angle) ? a : b
    }
  })

  // Starting from the top edge, walk around the edges finding the most counterclockwise edge
  let current = topEdge, closed = false, t = 1
  let poly = [topEdge]
  let _wG_1 = 0; while ((!closed && t < N * 10) && ++_wG_1 < 20000) { // Add some loop protection
    t++
    // Find edges starting on the current edge's end
    let candidates = [...edges].filter((e) => {
      return areEqualPoints(e.getStartpoint(), current.getEndpoint()) &&
        e !== current
    })
    // Next one is the most counterclockwise
    let next = candidates.reduce((a, b) => {
      let a1 = W(a.angle)
      let b1 = W(b.angle)
      let base = F(W(current.angle) + 180)
      let d1 = F(a1 - base)
      let d2 = F(b1 - base)
      return d1 > d2 ? a : b
    })

    if (next) {
      current = next
      poly.push(current)
      if (areEqualPoints(current.getStartpoint(), topEdge.getStartpoint())) {
        closed = true
      }
      if (t >= N * 10) {
        console.error('TOO MANY ITERATIONS')
      }
    } else {
      console.error('Error iterating edges') // Should not happen
    }
  }

  // TODO: Detect "holes" in the polygon, and add a contour so the polygon has a hole
  // It should go like this: for each edge on the polygon, check if there is a corresponding
  // edge in the opposite direction. If there is not, and the edge is not on the border
  // polygon, then is a hole. Use the same algorithm as for border detection, but use
  // the clockwise direction when walking around the edges.

  return poly
}

function drawBiomes(diagram) {
  for (let biome of BIOMES) {
    let cluster = biome.cluster
    let perimeter = biome.perimeter
    let smoothedPerimeter = biome.smoothedPerimeter
    if (!smoothedPerimeter) {
      let shape = perimeter.map((e) => {
        let cell
        if (e.edge.lSite && cluster.cells.some(c => c.site.voronoiId === e.edge.lSite.voronoiId)) {
          cell = DIAGRAM.cells[e.edge.lSite.voronoiId]
        } else if (e.edge.rSite && cluster.cells.some(c => c.site.voronoiId === e.edge.rSite.voronoiId)) {
          cell = DIAGRAM.cells[e.edge.rSite.voronoiId]
        } else {
          console.error('Cell not found')
        }
        let points = cell.halfedges.map((h) => { return h.getStartpoint() })
        let centroid = getCentroid(points)

        let p = e.getStartpoint()
        let vector = createVector(p.x - centroid.x, p.y - centroid.y)
        let m = vector.mag() - SEPARATOR
        vector.normalize()
        vector.mult(m)
        return [vector.x + centroid.x, vector.y + centroid.y]
      })
      biome.smoothedPerimeter = smoothLine(shape, ROUNDED_RADIUS, { closed: true }).reverse()
      smoothedPerimeter = biome.smoothedPerimeter
    }

    beginShape()
    let b = cluster.type
    let c = color(palette[b])
    stroke(c)
    noFill()
    strokeWeight(2)
    beginShape()
    for (let p of smoothedPerimeter) {
      vertex(p[0], p[1])
    }
    endShape(CLOSE)
  }
}

function generateVoronoi(points) {
  if (VORONOI && DIAGRAM) {
    VORONOI.recycle(DIAGRAM)
  } else {
    VORONOI = VORONOI || new Voronoi()
  }
  let bbox = {
    xl: 0,
    xr: canvasWidth,
    yt: 0,
    yb: canvasHeight,
  }
  let diagram = VORONOI.compute(points, bbox)
  return diagram
}

function drawVoronoi(diagram) {
  for (let cell of diagram.cells) {
    let smoothedCell = cell.smoothedCell
    if (!smoothedCell) {
      let points = cell.halfedges.map((halfEdge) => halfEdge.getEndpoint())
      let centroid = getCentroid(points)
      let closedPoints = points.map(({ x, y }) => {
        let vector = createVector(centroid.x - x, centroid.y - y)
        let m = vector.mag() - (SEPARATOR/2)
        vector.normalize()
        vector.mult(m)
        return [centroid.x - vector.x, centroid.y - vector.y]
      })

      cell.smoothedCell = smoothLine(closedPoints, ROUNDED_RADIUS, {
        includeEnds: true,
        stepSize: 2,
      })
      smoothedCell = cell.smoothedCell
    }

    let b = getBiomeIndex(cell.site.x, cell.site.y)
    let c = color(palette[b])
    c.setAlpha(80)
    fill(c)
    noStroke()
    beginShape()
    for (let [px, py] of smoothedCell) {
      vertex(px, py)
    }
    endShape()
    // Draw point for debugging
    // stroke(0)
    // strokeWeight(3)
    // point(cell.site.x, cell.site.y)
  }
  drawBiomes(diagram)
}

function getCentroid(pts) {
  var first = pts[0],
    last = pts[pts.length - 1]
  if (first.x != last.x || first.y != last.y) pts.push(first)
  var twiceArea = 0,
    x = 0,
    y = 0,
    nPts = pts.length,
    p1,
    p2,
    f
  for (var i = 0, j = nPts - 1; i < nPts; j = i++) {
    p1 = pts[i]
    p2 = pts[j]
    f = p1.x * p2.y - p2.x * p1.y
    twiceArea += f
    x += (p1.x + p2.x) * f
    y += (p1.y + p2.y) * f
  }
  f = twiceArea * 3
  return { x: x / f, y: y / f }
}


